const PAGE_ID = '1348081288382156';
let out = { route: 'skip', challenge: '', externalId: '', userId: '', displayName: '', message: '', postId: '', permalink: '', source: 'facebook', reason: '' };
try {
  const items = $input.all();
  const p = (items && items[0] && items[0].json) ? items[0].json : {};
  const query = p.query || {};
  const mode = query['hub.mode'] || p['hub.mode'] || '';
  if (mode === 'subscribe') {
    out.route = 'verify';
    out.challenge = String(query['hub.challenge'] || p['hub.challenge'] || '');
    return [{ json: out }];
  }
  let data = (p.body !== undefined && p.body !== null) ? p.body : p;
  if (typeof data === 'string') { data = JSON.parse(data); }
  if (!data || typeof data !== 'object') { data = {}; }
  const entries = Array.isArray(data.entry) ? data.entry : [];
  for (const en of entries) {
    const chs = Array.isArray(en.changes) ? en.changes : [];
    for (const ch of chs) {
      const v = ch.value || {};
      const from = v.from || {};
      const fromId = String(from.id || '');
      const msg = String(v.message || v.text || '').slice(0, 2000);
      const low = msg.toLowerCase();
      // --- LOOP GUARDS (must run before the keyword check) ---
      // 1. Ignore our own Page comments/replies (they re-trigger the feed webhook).
      if (fromId === PAGE_ID) { out.route = 'skip'; out.reason = 'self-page'; continue; }
      // 2. Ignore edits/removals.
      if (v.verb !== 'add') { out.route = 'skip'; out.reason = 'verb-' + String(v.verb); continue; }
      if (v.item !== 'comment') { out.route = 'skip'; out.reason = 'item-' + String(v.item); continue; }
      // 3. Ignore our own reply text (defence in depth if from.id is absent).
      if (low.indexOf('aqui tienes el link') >= 0 || low.indexOf('gracias') >= 0) { out.route = 'skip'; out.reason = 'own-reply-text'; continue; }
      // 4. Require an explicit keyword.
      const hit = (low.indexOf('link') >= 0) || (low.indexOf('enlace') >= 0);
      if (!hit) { out.route = 'skip'; out.reason = 'no-keyword'; continue; }
      out.route = 'lead';
      out.reason = 'match';
      out.externalId = String(v.comment_id || v.id || '');
      out.userId = fromId;
      out.displayName = from.name || 'Social lead';
      out.message = msg;
      out.postId = String(v.post_id || (v.post && v.post.id) || '');
      out.permalink = String((v.post && v.post.permalink_url) || '');
    }
  }
} catch (err) { out.route = 'skip'; out.reason = 'error'; }
return [{ json: out }];

const d = $input.first().json;
const now = new Date().toISOString();
const name = d.displayName || 'Social lead';
const parts = name.trim().split(/\s+/);
const lastName = parts.pop() || name;
const firstName = parts.join(' ');
return [{ json: {
  externalId: d.externalId, userId: d.userId, name: name, firstName: firstName, lastName: lastName,
  message: d.message || '', postId: d.postId || '', permalink: d.permalink || '', source: d.source || 'facebook',
  sourceCrm: 'zoho', sourceClient: 'growbusy-main',
  consent: { emailMarketing: false, smsMarketing: false, version: 'v1', capturedAt: now }, capturedAt: now
} }];
